export type ParsedSwapInstruction<
  TProgram extends string = typeof MOCK_MARKET_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    user: TAccountMetas[0];
    market: TAccountMetas[1];
    mintIn: TAccountMetas[2];
    mintOut: TAccountMetas[3];
    feedIn: TAccountMetas[4];
    feedOut: TAccountMetas[5];
    userAtaIn: TAccountMetas[6];
    userAtaOut: TAccountMetas[7];
    tokenProgramIn: TAccountMetas[8];
    tokenProgramOut: TAccountMetas[9];
  };
  data: SwapInstructionData;
};

export function parseSwapInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedSwapInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      user: getNextAccount(),
      market: getNextAccount(),
      mintIn: getNextAccount(),
      mintOut: getNextAccount(),
      feedIn: getNextAccount(),
      feedOut: getNextAccount(),
      userAtaIn: getNextAccount(),
      userAtaOut: getNextAccount(),
      tokenProgramIn: getNextAccount(),
      tokenProgramOut: getNextAccount(),
    },
    data: getSwapInstructionDataDecoder().decode(instruction.data),
  };
}
